// Generated by scripts/generate-extension-page.py; shared browser extension UI.
export const EXTENSION_BRIDGE_HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\" />\n  <!--\n    CSP: only esm.sh (the @polkadot/extension-dapp import below) and this page's\n    own inline script may run; network access is limited to the local bridge\n    websocket. 'unsafe-inline' is required because the bridge script is inline.\n    TODO: vendor @polkadot/extension-dapp locally (SRI cannot cover a bare ESM\n    import) so the esm.sh origin can be dropped entirely.\n  -->\n  <meta http-equiv=\"Content-Security-Policy\"\n        content=\"default-src 'none'; script-src 'unsafe-inline' https://esm.sh; connect-src 'self' ws://127.0.0.1:* ws://localhost:* https://esm.sh; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'; object-src 'none'\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n  <title>Bittensor Extension Bridge</title>\n  <style>\n    /* Shared local-page theme (see vault/static/vault.html): bittensor.com's\n       light look \u2014 white ground, #292929 ink, thin dark borders, #2f46f4\n       accent, Haffer-style sans + DM Mono labels. */\n    :root {\n      color-scheme: light;\n      --background: #ffffff;\n      --ink: #292929;\n      --muted: #757575;\n      --line: #262626;\n      --line-soft: #e3e3e3;\n      --accent: #2f46f4;\n      --success: #49c24e;\n      --error: #d93737;\n      --sans: Haffer, HafferSQ, \"Helvetica Neue\", Arial, system-ui, -apple-system, sans-serif;\n      --mono: \"DM Mono\", FiraCode, \"Fira Code\", ui-monospace, SFMono-Regular, Menlo, monospace;\n    }\n\n    * { box-sizing: border-box; }\n\n    html, body {\n      min-height: 100%;\n      margin: 0;\n    }\n\n    body {\n      background: var(--background);\n      color: var(--ink);\n      font-family: var(--sans);\n    }\n\n    /* Top bar: same anatomy as bittensor.com's header (and the vault signing\n       page) \u2014 \u03c4 logo left in a 105px slot, mono uppercase page name centered,\n       session status right where the site puts its wallet widget. */\n    .topbar {\n      display: flex;\n      flex-direction: row;\n      justify-content: space-between;\n      align-items: center;\n      padding: 32px;\n      font-family: var(--mono);\n      font-size: 0.78rem;\n      letter-spacing: 0.03em;\n    }\n\n    .topbar .logo {\n      width: 105px;\n      display: flex;\n      align-items: center;\n    }\n\n    .topbar .logo svg {\n      width: 21px;\n      height: 23px;\n      color: var(--ink);\n    }\n\n    .topbar .page-name {\n      flex-grow: 1;\n      display: flex;\n      justify-content: center;\n      text-transform: uppercase;\n      color: var(--ink);\n    }\n\n    .topbar .session {\n      width: 105px;\n      display: flex;\n      justify-content: flex-end;\n      align-items: center;\n      gap: 0.5rem;\n      color: var(--muted);\n      text-transform: uppercase;\n    }\n\n    .topbar .session .dot {\n      width: 0.45rem;\n      height: 0.45rem;\n      border-radius: 50%;\n      background: var(--line-soft);\n    }\n\n    body[data-bridge-state=\"ready\"] .topbar .session .dot,\n    body[data-bridge-state=\"authorizing\"] .topbar .session .dot { background: var(--accent); }\n    body[data-bridge-state=\"complete\"] .topbar .session .dot { background: var(--success); }\n    body[data-bridge-state=\"failed\"] .topbar .session .dot,\n    body[data-bridge-state=\"error\"] .topbar .session .dot { background: var(--error); }\n\n    .shell {\n      display: grid;\n      grid-template-columns: minmax(18rem, 26rem);\n      justify-content: center;\n      align-content: center;\n      gap: clamp(1.5rem, 4vw, 3rem);\n      min-height: calc(100vh - 87px);\n      padding: clamp(1.5rem, 5vw, 4rem);\n      padding-top: 0;\n    }\n\n    .status {\n      justify-self: center;\n      text-align: center;\n      max-width: 44rem;\n      margin-bottom: 0.5rem;\n    }\n\n    .status h1 {\n      margin: 0;\n      font-size: clamp(1.7rem, 3.4vw, 2.5rem);\n      font-weight: 400;\n      letter-spacing: -0.01em;\n      line-height: 1.1;\n    }\n\n    .status p {\n      margin: 0.7rem 0 0;\n      color: var(--muted);\n      font-family: var(--mono);\n      font-size: 0.85rem;\n    }\n\n    .panel {\n      border: 1px solid var(--line);\n      background: var(--background);\n    }\n\n    .panel-bar {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      height: 2.4rem;\n      padding: 0 0.9rem;\n      border-bottom: 1px solid var(--line);\n      color: var(--ink);\n      font-family: var(--mono);\n      font-size: 0.72rem;\n      letter-spacing: 0.14em;\n      text-transform: uppercase;\n    }\n\n    .panel-bar .dot {\n      width: 0.45rem;\n      height: 0.45rem;\n      border-radius: 50%;\n      background: var(--line-soft);\n    }\n\n    .panel-body {\n      padding: 1.1rem;\n      display: grid;\n      gap: 0.9rem;\n      justify-items: center;\n    }\n\n    /* Connected wallet extensions: one row each, with a toggle deciding\n       whether that extension's accounts are offered to btcli. */\n    .ext-list {\n      width: 100%;\n      display: grid;\n      border: 1px solid var(--line-soft);\n    }\n\n    .ext-row {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      gap: 0.8rem;\n      padding: 0.75rem 0.9rem;\n    }\n\n    .ext-row + .ext-row {\n      border-top: 1px solid var(--line-soft);\n    }\n\n    .ext-row .ext-id {\n      display: grid;\n      gap: 0.15rem;\n      min-width: 0;\n    }\n\n    .ext-row .ext-name {\n      font-size: 0.92rem;\n      color: var(--ink);\n    }\n\n    .ext-row .ext-detail {\n      font-family: var(--mono);\n      font-size: 0.72rem;\n      color: var(--muted);\n    }\n\n    .ext-row.disabled .ext-name,\n    .ext-row.disabled .ext-detail {\n      color: var(--line-soft);\n    }\n\n    .ext-toggle {\n      appearance: none;\n      width: 2.1rem;\n      height: 1.15rem;\n      border: 1px solid var(--line);\n      border-radius: 1rem;\n      position: relative;\n      cursor: pointer;\n      flex-shrink: 0;\n      background: var(--background);\n    }\n\n    .ext-toggle::after {\n      content: \"\";\n      position: absolute;\n      top: 0.14rem;\n      left: 0.14rem;\n      width: 0.72rem;\n      height: 0.72rem;\n      border-radius: 50%;\n      background: var(--line-soft);\n      transition: transform 120ms ease, background 120ms ease;\n    }\n\n    .ext-toggle:checked::after {\n      transform: translateX(0.9rem);\n      background: var(--accent);\n    }\n\n    .ext-empty {\n      padding: 0.9rem;\n      font-family: var(--mono);\n      font-size: 0.78rem;\n      color: var(--muted);\n      text-align: center;\n    }\n\n    .hint {\n      color: var(--muted);\n      font-size: 0.88rem;\n      line-height: 1.5;\n      text-align: center;\n      margin: 0;\n    }\n\n    .hint code {\n      font-family: var(--mono);\n      font-size: 0.78rem;\n      color: var(--ink);\n      border: 1px solid var(--line-soft);\n      padding: 0.05rem 0.3rem;\n      white-space: nowrap;\n    }\n\n    body[data-bridge-state=\"ready\"] .panel-bar .dot,\n    body[data-bridge-state=\"authorizing\"] .panel-bar .dot { background: var(--accent); }\n    body[data-bridge-state=\"complete\"] .panel-bar .dot { background: var(--success); }\n    body[data-bridge-state=\"complete\"] .panel { border-color: var(--success); }\n    body[data-bridge-state=\"failed\"] .panel-bar .dot,\n    body[data-bridge-state=\"error\"] .panel-bar .dot { background: var(--error); }\n    body[data-bridge-state=\"failed\"] .panel,\n    body[data-bridge-state=\"error\"] .panel { border-color: var(--error); }\n    body[data-bridge-state=\"failed\"] .status h1,\n    body[data-bridge-state=\"error\"] .status h1 { color: var(--error); }\n  </style>\n</head>\n<body data-bridge-state=\"connecting\">\n  <header class=\"topbar\">\n    <div class=\"logo\">\n      <a href=\"https://bittensor.com\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Bittensor\">\n        <!-- \u03c4 logo (website/packages/ui/assets/TaoLogo.svg) -->\n        <svg width=\"21\" height=\"23\" viewBox=\"0 0 21 23\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n          <path d=\"M12.5309 17.7832V8.70318C12.5238 7.60933 12.0844 6.56266 11.3087 5.79143C10.533 5.02019 9.48378 4.58695 8.38991 4.58618V19.0972C8.38387 19.6135 8.48312 20.1256 8.6816 20.6023C8.88007 21.0789 9.17361 21.5102 9.54428 21.8696C9.91496 22.2291 10.355 22.5092 10.8376 22.6929C11.3201 22.8766 11.835 22.9601 12.3509 22.9382C13.3561 23.0064 14.353 22.7174 15.1659 22.1222C12.7769 21.8692 12.5309 20.4292 12.5309 17.7832Z\" fill=\"currentColor\"/>\n          <path d=\"M3.775 0.787109C2.77152 0.793711 1.81138 1.19698 1.10414 1.9089C0.396901 2.62083 -2.17165e-05 3.5836 8.91144e-10 4.58711H16.893C17.8965 4.58051 18.8566 4.17724 19.5639 3.46531C20.2711 2.75339 20.668 1.79062 20.668 0.787109H3.775Z\" fill=\"currentColor\"/>\n        </svg>\n      </a>\n    </div>\n    <div class=\"page-name\">Extension bridge</div>\n    <div class=\"session\"><span class=\"dot\" aria-hidden=\"true\"></span><span id=\"session-state\">local</span></div>\n  </header>\n  <main class=\"shell\">\n    <div class=\"status\">\n      <h1 id=\"headline\">Keep this page open</h1>\n      <p id=\"detail\">Switch back to btcli.</p>\n    </div>\n\n    <section class=\"panel\">\n      <div class=\"panel-bar\"><span>connected extensions</span><span class=\"dot\" aria-hidden=\"true\"></span></div>\n      <div class=\"panel-body\">\n        <div class=\"ext-list\" id=\"ext-list\">\n          <div class=\"ext-empty\">waiting for wallet extensions\u2026</div>\n        </div>\n        <p class=\"hint\">\n          btcli talks to your wallet extensions through this page. Toggle an\n          extension off to hide its accounts from btcli; signing requests\n          appear as extension popups \u2014 approve or reject them there.\n        </p>\n        <p class=\"hint\">\n          Wrong browser? If your wallet lives elsewhere, make this page open\n          there instead: <code>btcli config set extension_browser firefox</code>\n          (or pass <code>--extension-browser</code> per command).\n        </p>\n      </div>\n    </section>\n  </main>\n  <script type=\"module\">\n    import { web3Accounts, web3Enable, web3FromAddress } from \"https://esm.sh/@polkadot/extension-dapp@0.46.9\";\n\n    const APP_NAME = \"Bittensor SDK\";\n    const headlineEl = document.getElementById(\"headline\");\n    const detailEl = document.getElementById(\"detail\");\n    const extListEl = document.getElementById(\"ext-list\");\n    const wsUrl = `${location.protocol === \"https:\" ? \"wss\" : \"ws\"}://${location.host}/ws`;\n    const bridgeSession = new URLSearchParams(location.search).get(\"session\") || \"\";\n    let ws;\n    let extensionsEnabled = false;\n    // Extensions web3Enable authorized: [{name, version}]. Account sources\n    // use the same name key.\n    let knownExtensions = [];\n    let accountsBySource = {};\n    // Page-side extension filter, remembered across bridge sessions.\n    const DISABLED_KEY = \"bittensorBridgeDisabledSources\";\n    let disabledSources = new Set(JSON.parse(localStorage.getItem(DISABLED_KEY) || \"[]\"));\n\n    function persistDisabled() {\n      localStorage.setItem(DISABLED_KEY, JSON.stringify([...disabledSources]));\n    }\n\n    function renderExtensions() {\n      if (!knownExtensions.length) {\n        extListEl.innerHTML = '<div class=\"ext-empty\">no wallet extensions connected</div>';\n        return;\n      }\n      extListEl.innerHTML = \"\";\n      for (const ext of knownExtensions) {\n        const row = document.createElement(\"div\");\n        row.className = \"ext-row\" + (disabledSources.has(ext.name) ? \" disabled\" : \"\");\n        const id = document.createElement(\"div\");\n        id.className = \"ext-id\";\n        const name = document.createElement(\"span\");\n        name.className = \"ext-name\";\n        name.textContent = ext.name;\n        const detail = document.createElement(\"span\");\n        detail.className = \"ext-detail\";\n        const count = (accountsBySource[ext.name] || []).length;\n        detail.textContent = `v${ext.version || \"?\"} \u00b7 ${count} account${count === 1 ? \"\" : \"s\"}` +\n          (disabledSources.has(ext.name) ? \" \u00b7 hidden from btcli\" : \"\");\n        id.append(name, detail);\n        const toggle = document.createElement(\"input\");\n        toggle.type = \"checkbox\";\n        toggle.className = \"ext-toggle\";\n        toggle.checked = !disabledSources.has(ext.name);\n        toggle.title = toggle.checked\n          ? `hide ${ext.name} accounts from btcli`\n          : `offer ${ext.name} accounts to btcli`;\n        toggle.addEventListener(\"change\", () => {\n          if (toggle.checked) disabledSources.delete(ext.name);\n          else disabledSources.add(ext.name);\n          persistDisabled();\n          renderExtensions();\n        });\n        row.append(id, toggle);\n        extListEl.appendChild(row);\n      }\n    }\n\n    const STATE_LABELS = {\n      connecting: \"connecting\",\n      ready: \"connected\",\n      authorizing: \"in progress\",\n      complete: \"complete\",\n      failed: \"failed\",\n      error: \"error\",\n    };\n\n    function setBridgeState(state) {\n      document.body.dataset.bridgeState = state;\n      document.getElementById(\"session-state\").textContent = STATE_LABELS[state] || state;\n    }\n\n    function showCopy(headline, detail) {\n      headlineEl.textContent = headline;\n      detailEl.textContent = detail;\n    }\n\n    function showError(headline, detail) {\n      setBridgeState(\"error\");\n      showCopy(headline, detail);\n    }\n\n    function showReady() {\n      setBridgeState(\"ready\");\n      showCopy(\n        \"Connected to btcli\",\n        \"A signing popup appears here when a transaction is ready.\"\n      );\n    }\n\n    function showSubmitting() {\n      setBridgeState(\"authorizing\");\n      showCopy(\"Signature sent\", \"btcli is submitting the transaction\u2026\");\n    }\n\n    function showSigning(source, stage) {\n      setBridgeState(\"authorizing\");\n      const hint = stage\n        ? `${stage}. Confirm or reject the signature request in the extension popup.`\n        : \"Confirm or reject the signature request in the extension popup.\";\n      showCopy(\n        source ? `Approve in ${source}` : \"Approve in your wallet\",\n        hint\n      );\n    }\n\n    function showSignError(error) {\n      showError(\n        \"Signing failed\",\n        error?.message || String(error) || \"Switch back to btcli for details.\"\n      );\n    }\n\n    function showTransactionResult(success) {\n      setBridgeState(success ? \"complete\" : \"failed\");\n      showCopy(\n        success ? \"Transaction complete\" : \"Transaction failed\",\n        success ? \"This tab closes itself in a moment.\" : \"Switch back to btcli.\"\n      );\n      if (success) {\n        closeTabSoon();\n      }\n    }\n\n    // Close this tab once the flow is done. Browsers only let a script close\n    // tabs it (or an external opener) created with no further history \u2014 which\n    // is exactly how btcli opens this page. If the browser refuses, fall back\n    // to telling the user.\n    function closeTabSoon(delayMs = 1200) {\n      setTimeout(() => {\n        window.close();\n        setTimeout(() => {\n          if (!document.hidden) {\n            showCopy(\"Transaction complete\", \"You can close this tab.\");\n          }\n        }, 400);\n      }, delayMs);\n    }\n\n    async function ensureExtensions() {\n      if (extensionsEnabled) {\n        return;\n      }\n      setBridgeState(\"authorizing\");\n      const extensions = await web3Enable(APP_NAME);\n      if (!extensions.length) {\n        renderExtensions();\n        throw new Error(\"No compatible wallet extension found. Install Talisman or Polkadot.js in this browser.\");\n      }\n      extensionsEnabled = true;\n      knownExtensions = extensions.map((ext) => ({ name: ext.name, version: ext.version }));\n      renderExtensions();\n      setBridgeState(\"ready\");\n    }\n\n    async function listAccounts() {\n      await ensureExtensions();\n      const accounts = (await web3Accounts()).map((account) => ({\n        address: account.address,\n        name: account.meta?.name || account.address,\n        meta: {\n          name: account.meta?.name || account.address,\n          source: account.meta?.source || \"unknown\",\n        },\n        source: account.meta?.source || \"unknown\",\n        type: account.type || \"sr25519\",\n      }));\n      accountsBySource = {};\n      for (const account of accounts) {\n        (accountsBySource[account.source] ??= []).push(account);\n      }\n      renderExtensions();\n      return accounts.filter((account) => !disabledSources.has(account.source));\n    }\n\n    function sourceOf(address) {\n      for (const [source, accounts] of Object.entries(accountsBySource)) {\n        if (accounts.some((account) => account.address === address)) return source;\n      }\n      return null;\n    }\n\n    function assertSourceEnabled(address) {\n      const source = sourceOf(address);\n      if (source && disabledSources.has(source)) {\n        throw new Error(\n          `the account belongs to ${source}, which is toggled off on the bridge page \u2014 enable it and retry`\n        );\n      }\n      return source;\n    }\n\n    async function signExtrinsic(params) {\n      const payload = params?.payload;\n      if (!payload?.address) {\n        throw new Error(\"missing payload.address\");\n      }\n      await ensureExtensions();\n      const source = assertSourceEnabled(payload.address);\n      showSigning(source, params.stage);\n      const injector = await web3FromAddress(payload.address);\n      const signature = await injector.signer.signPayload(payload);\n      if (!params.moreComing) {\n        showSubmitting();\n      }\n      return signature;\n    }\n\n    async function signBytes(params) {\n      const address = params?.address;\n      const data = params?.data;\n      if (!address || !data) {\n        throw new Error(\"missing address or data\");\n      }\n      await ensureExtensions();\n      const source = assertSourceEnabled(address);\n      showSigning(source);\n      const injector = await web3FromAddress(address);\n      const signature = await injector.signer.signRaw({\n        address,\n        data,\n        type: params?.type || \"bytes\",\n      });\n      showSubmitting();\n      return signature;\n    }\n\n    async function handleRequest(request) {\n      switch (request.method) {\n        case \"accounts.list\":\n          return { accounts: await listAccounts() };\n        case \"extrinsic.sign\":\n          return await signExtrinsic(request.params || {});\n        case \"bytes.sign\":\n          return await signBytes(request.params || {});\n        case \"transaction.result\":\n          showTransactionResult(request.params?.success === true);\n          return { acknowledged: true };\n        default:\n          throw new Error(`unsupported method ${request.method}`);\n      }\n    }\n\n    function connect() {\n      ws = new WebSocket(wsUrl);\n      ws.onopen = () => {\n        ws.send(JSON.stringify({ role: \"bridge\", session: bridgeSession }));\n        setBridgeState(\"authorizing\");\n        showCopy(\"Connecting your wallet\", \"Authorize the extension if it asks.\");\n        listAccounts()\n          .then(() => {\n            // Don't clobber a signing prompt that raced ahead of the warm-up.\n            if (headlineEl.textContent === \"Connecting your wallet\") showReady();\n          })\n          .catch((error) => {\n            showError(\n              \"Authorization failed\",\n              error.message || String(error)\n            );\n          });\n      };\n      ws.onclose = (event) => {\n        if (event.code === 1008 || event.code === 1012) {\n          // Stale or replaced session: this tab can do nothing further, so\n          // try to get out of the way instead of piling up.\n          showError(\n            \"Stale session\",\n            \"This bridge tab is stale \u2014 a fresh one opens with the next btcli run.\"\n          );\n          setTimeout(() => window.close(), 800);\n          return;\n        }\n        setBridgeState(\"connecting\");\n        showCopy(\"Reconnecting\", \"Bridge disconnected. Reconnecting\u2026\");\n        setTimeout(connect, 1500);\n      };\n      ws.onerror = () => {\n        showError(\"Connection error\", \"WebSocket error. Check that btcli is still running.\");\n      };\n      ws.onmessage = async (event) => {\n        let request;\n        try {\n          request = JSON.parse(event.data);\n        } catch {\n          return;\n        }\n        if (!request?.id || !request?.method) {\n          return;\n        }\n        try {\n          const result = await handleRequest(request);\n          ws.send(JSON.stringify({ id: request.id, result }));\n        } catch (error) {\n          // Always return the error to btcli; also surface sign/account failures\n          // on this page so a wallet rejection doesn't leave \"Keep this page open\".\n          if (request.method === \"extrinsic.sign\" || request.method === \"bytes.sign\") {\n            showSignError(error);\n          } else if (request.method === \"accounts.list\") {\n            showError(\"Authorization failed\", error.message || String(error));\n          }\n          ws.send(JSON.stringify({ id: request.id, error: { message: error.message || String(error) } }));\n        }\n      };\n    }\n\n    connect();\n  </script>\n</body>\n</html>\n"
